// Package cli implements a minimal command-line framework that reproduces
// the externally visible behavior of the cobra/pflag based CLI of the
// reference tool: help layout, flag parsing semantics and error messages.
package cli

import (
	"fmt"
	"os"
	"sort"
	"strings"
)

// Command describes a CLI command node.
type Command struct {
	Use     string // e.g. "inspect" or "apply [flags] [amount]"
	Short   string
	Long    string
	Example string
	Args    PositionalArgs
	Flags   []*Flag
	Run     func(c *Command, args []string) error

	parent   *Command
	commands []*Command
}

// PositionalArgs validates positional arguments.
type PositionalArgs func(c *Command, args []string) error

// Flag describes a single flag.
type Flag struct {
	Name      string
	Shorthand string
	// Kind is one of: "string", "strings", "bool", "uint", "duration", "vars".
	Kind    string
	Usage   string
	Default string // default value rendered in help; empty means none.
	Hidden  bool

	// Value holds the parsed value(s) after Parse.
	StrVal  string
	StrsVal []string
	BoolVal bool
	Changed bool
}

// Lookup returns the flag by name.
func (c *Command) Lookup(name string) *Flag {
	for _, f := range c.Flags {
		if f.Name == name {
			return f
		}
	}
	return nil
}

// AddCommand adds subcommands.
func (c *Command) AddCommand(subs ...*Command) {
	for _, s := range subs {
		s.parent = c
		c.commands = append(c.commands, s)
	}
}

// Commands returns sorted subcommands.
func (c *Command) Commands() []*Command {
	out := make([]*Command, len(c.commands))
	copy(out, c.commands)
	sort.Slice(out, func(i, j int) bool { return out[i].Name() < out[j].Name() })
	return out
}

// Name returns the command name (first word of Use).
func (c *Command) Name() string {
	name := c.Use
	if i := strings.Index(name, " "); i != -1 {
		name = name[:i]
	}
	return name
}

// UseLine returns the full usage line, e.g. "atlas schema inspect [flags]".
func (c *Command) UseLine() string {
	var parts []string
	for p := c; p != nil; p = p.parent {
		parts = append([]string{p.Use}, parts...)
	}
	line := strings.Join(parts, " ")
	if !c.HasSubCommands() && !strings.Contains(line, "[flags]") {
		line += " [flags]"
	}
	return line
}

// HasSubCommands reports whether the command has subcommands.
func (c *Command) HasSubCommands() bool { return len(c.commands) > 0 }

// Root returns the root command.
func (c *Command) Root() *Command {
	for c.parent != nil {
		c = c.parent
	}
	return c
}

// CommandPath returns e.g. "atlas schema inspect".
func (c *Command) CommandPath() string {
	var parts []string
	for p := c; p != nil; p = p.parent {
		parts = append([]string{p.Name()}, parts...)
	}
	return strings.Join(parts, " ")
}

// Find traverses the command tree for the given args path.
func (c *Command) Find(args []string) (*Command, []string, error) {
	return c.find(args)
}

func (c *Command) find(args []string) (*Command, []string, error) {
	if len(args) == 0 {
		return c, nil, nil
	}
	for _, sub := range c.commands {
		if sub.Name() == args[0] {
			return sub.find(args[1:])
		}
	}
	return c, args, nil
}

func (c *Command) findSuggestion(args []string) *Command {
	cur := c
	for _, a := range args {
		found := false
		for _, sub := range cur.commands {
			if sub.Name() == a {
				cur = sub
				found = true
				break
			}
		}
		if !found {
			break
		}
	}
	return cur
}

// Execute runs the command tree with OS args.
func (c *Command) Execute() {
	cmd, args, err := c.ExecuteC(os.Args[1:])
	if err != nil {
		// Error printing handled by caller via OnError hook.
		if ErrorHandler != nil {
			ErrorHandler(err)
		}
		fmt.Fprintln(os.Stderr, "Error:", err.Error())
		os.Exit(1)
	}
	_ = cmd
	_ = args
}

// ErrorHandler is called on execution error before printing the message.
var ErrorHandler func(err error)

// ExecuteC parses and executes, returning the found command.
func (c *Command) ExecuteC(argv []string) (*Command, []string, error) {
	// Find the target command by walking non-flag args.
	var path []string
	i := 0
	for i < len(argv) {
		a := argv[i]
		if strings.HasPrefix(a, "-") {
			break
		}
		path = append(path, a)
		i++
		// stop at first non-matching segment
		cmd, rest, _ := c.find(path)
		if len(rest) > 0 {
			break
		}
		_ = cmd
	}
	cmd, rest, _ := c.find(path)
	// If some path segments didn't match, they may be positional args.
	target := cmd
	var positional []string
	positional = append(positional, rest...)
	positional = append(positional, argv[len(path):]...)

	// Special case: "help" command.
	if target.Name() == "help" && target.parent == nil {
		hc := target
		_ = hc
	}

	// Unknown command handling: if root and first arg is not a flag and no match.
	if target == c && len(rest) > 0 && c.HasSubCommands() {
		return nil, nil, &UnknownCommandError{Cmd: c, Arg: rest[0]}
	}
	// If a matched parent command has subcommands but an unknown sub was given:
	if target.HasSubCommands() && len(rest) > 0 {
		// Behave like the reference: print help of the group, exit 0.
		return nil, nil, &GroupHelpError{Cmd: target}
	}

	// Parse flags.
	args := positional
	parsed, err := target.ParseFlags(args)
	if err != nil {
		return nil, nil, err
	}
	// help flag
	if target.Lookup("help") != nil && target.Lookup("help").BoolVal {
		fmt.Print(target.HelpText())
		return target, nil, nil
	}
	if target.Args != nil {
		if err := target.Args(target, parsed); err != nil {
			return nil, nil, err
		}
	}
	if target.Run == nil {
		fmt.Print(target.HelpText())
		return target, nil, nil
	}
	if err := target.Run(target, parsed); err != nil {
		return nil, nil, err
	}
	return target, parsed, nil
}

// UnknownCommandError is returned for unknown commands.
type UnknownCommandError struct {
	Cmd *Command
	Arg string
}

func (e *UnknownCommandError) Error() string {
	return fmt.Sprintf("unknown command %q for %q", e.Arg, e.Cmd.CommandPath())
}

// GroupHelpError signals printing the group help with exit 0.
type GroupHelpError struct{ Cmd *Command }

func (e *GroupHelpError) Error() string { return "group help" }

// UnknownFlagError is returned for unknown flags.
type UnknownFlagError struct{ Name string }

func (e *UnknownFlagError) Error() string { return "unknown flag: --" + e.Name }

// RequiredFlagsError is returned when required flags are missing.
type RequiredFlagsError struct{ Names []string }

func (e *RequiredFlagsError) Error() string {
	quoted := make([]string, len(e.Names))
	for i, n := range e.Names {
		quoted[i] = fmt.Sprintf("%q", n)
	}
	return "required flag(s) " + strings.Join(quoted, ", ") + " not set"
}

// RequiredAnnotations marks flags as required (stored separately).
var RequiredFlags = map[*Flag]bool{}

// MarkRequired marks a flag as required.
func MarkRequired(f *Flag) { RequiredFlags[f] = true }

// ParseFlags parses pflag-style flags interspersed with positional args.
func (c *Command) ParseFlags(args []string) ([]string, error) {
	var positional []string
	all := c.allFlags()
	i := 0
	for i < len(args) {
		a := args[i]
		switch {
		case a == "--":
			positional = append(positional, args[i+1:]...)
			i = len(args)
		case strings.HasPrefix(a, "--"):
			name := a[2:]
			var val string
			var hasVal bool
			if j := strings.Index(name, "="); j != -1 {
				val, name, hasVal = name[j+1:], name[:j], true
			}
			f := findFlag(all, name)
			if f == nil {
				if name == "help" {
					// implicit help flag exists on all commands
					f = c.Lookup("help")
				}
				if f == nil {
					return nil, &UnknownFlagError{Name: name}
				}
			}
			if f.Kind == "bool" {
				f.BoolVal = true
				if hasVal {
					f.BoolVal = val == "true"
				}
				f.Changed = true
			} else {
				if !hasVal {
					if i+1 >= len(args) {
						return nil, fmt.Errorf("flag needs an argument: --%s", name)
					}
					i++
					val = args[i]
				}
				setFlagValue(f, val)
			}
		case strings.HasPrefix(a, "-") && a != "-":
			shorts := a[1:]
			for len(shorts) > 0 {
				s := shorts[:1]
				shorts = shorts[1:]
				f := findShort(all, s)
				if f == nil {
					if s == "h" {
						f = c.Lookup("help")
					}
					if f == nil {
						return nil, fmt.Errorf("unknown shorthand flag: %q in -%s", s, s)
					}
				}
				if f.Kind == "bool" {
					f.BoolVal = true
					f.Changed = true
					continue
				}
				// needs value: rest of shorts or next arg
				if len(shorts) > 0 {
					v := shorts
					if strings.HasPrefix(v, "=") {
						v = v[1:]
					}
					setFlagValue(f, v)
					shorts = ""
				} else {
					if i+1 >= len(args) {
						return nil, fmt.Errorf("flag needs an argument: --%s", f.Name)
					}
					i++
					setFlagValue(f, args[i])
				}
			}
		default:
			positional = append(positional, a)
		}
		i++
	}
	// required flags
	var missing []string
	for _, f := range c.Flags {
		if RequiredFlags[f] && !f.Changed {
			missing = append(missing, f.Name)
		}
	}
	if len(missing) > 0 {
		return nil, &RequiredFlagsError{Names: missing}
	}
	return positional, nil
}

func setFlagValue(f *Flag, v string) {
	f.Changed = true
	switch f.Kind {
	case "strings":
		for _, p := range strings.Split(v, ",") {
			f.StrsVal = append(f.StrsVal, p)
		}
	case "vars":
		f.StrsVal = append(f.StrsVal, v)
	default:
		f.StrVal = v
	}
}

func findFlag(flags []*Flag, name string) *Flag {
	for _, f := range flags {
		if f.Name == name {
			return f
		}
	}
	return nil
}

func findShort(flags []*Flag, s string) *Flag {
	for _, f := range flags {
		if f.Shorthand == s {
			return f
		}
	}
	return nil
}

// allFlags returns flags including inherited (global) ones from parents.
func (c *Command) allFlags() []*Flag {
	var out []*Flag
	out = append(out, c.Flags...)
	for p := c.parent; p != nil; p = p.parent {
		out = append(out, p.Flags...)
	}
	return out
}

// localFlags returns only flags defined on this command.
func (c *Command) localFlags() []*Flag { return c.Flags }

// inheritedFlags returns flags from parents.
func (c *Command) inheritedFlags() []*Flag {
	var out []*Flag
	for p := c.parent; p != nil; p = p.parent {
		out = append(out, p.Flags...)
	}
	return out
}

// HelpText renders the full help for the command, cobra-style.
func (c *Command) HelpText() string {
	var b strings.Builder
	long := c.Long
	if long == "" {
		long = c.Short
	}
	if long != "" {
		b.WriteString(long)
		b.WriteString("\n")
	}
	b.WriteString("\nUsage:\n")
	if c.HasSubCommands() {
		b.WriteString("  " + c.CommandPath() + " [command]\n")
	} else {
		b.WriteString("  " + c.UseLine() + "\n")
	}
	if c.HasSubCommands() {
		b.WriteString("\nAvailable Commands:\n")
		cmds := c.Commands()
		max := 0
		for _, s := range cmds {
			if len(s.Name()) > max {
				max = len(s.Name())
			}
		}
		for _, s := range cmds {
			fmt.Fprintf(&b, "  %-*s %s\n", max+2, s.Name(), s.Short)
		}
	}
	if c.Example != "" {
		b.WriteString("\nExamples:\n")
		b.WriteString(c.Example)
		b.WriteString("\n")
	}
	local := c.visibleFlags(c.localFlags())
	if len(local) > 0 {
		b.WriteString("\nFlags:\n")
		b.WriteString(flagUsages(local))
	}
	inherited := c.visibleFlags(c.inheritedFlags())
	if len(inherited) > 0 {
		b.WriteString("\nGlobal Flags:\n")
		b.WriteString(flagUsages(inherited))
	}
	if c.HasSubCommands() {
		fmt.Fprintf(&b, "\nUse \"%s [command] --help\" for more information about a command.\n", c.CommandPath())
	}
	return b.String()
}

func (c *Command) visibleFlags(fs []*Flag) []*Flag {
	var out []*Flag
	for _, f := range fs {
		if !f.Hidden {
			out = append(out, f)
		}
	}
	// sort by name (pflag sorts lexicographically)
	sort.Slice(out, func(i, j int) bool { return out[i].Name < out[j].Name })
	return out
}

// flagUsageType returns the type string shown in help.
func (f *Flag) usageType() string {
	switch f.Kind {
	case "bool":
		return ""
	case "string":
		return "string"
	case "strings":
		return "strings"
	case "uint":
		return "uint"
	case "duration":
		return "duration"
	case "vars":
		return "<name>=<value>"
	}
	return f.Kind
}

func flagUsages(fs []*Flag) string {
	type line struct {
		prefix string
		usage  string
	}
	var lines []line
	max := 0
	for _, f := range fs {
		var p string
		if f.Shorthand != "" {
			p = "  -" + f.Shorthand + ", --" + f.Name
		} else {
			p = "      --" + f.Name
		}
		if t := f.usageType(); t != "" {
			p += " " + t
		}
		usage := f.Usage
		if f.Default != "" {
			usage += fmt.Sprintf(" (default %s)", f.Default)
		}
		lines = append(lines, line{p, usage})
		if len(p) > max {
			max = len(p)
		}
	}
	var b strings.Builder
	for _, l := range lines {
		b.WriteString(l.prefix)
		b.WriteString(strings.Repeat(" ", max-len(l.prefix)+4))
		b.WriteString(l.usage)
		b.WriteString("\n")
	}
	return b.String()
}

