package main

import (
	"embed"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"time"

	"atlasclone/cli"
)

//go:embed helptext
var helptextFS embed.FS

func helpText(name string) string {
	b, err := helptextFS.ReadFile("helptext/help_" + name + ".txt")
	if err != nil {
		panic(err)
	}
	return string(b)
}

// printHelp prints the captured help text for the command path.
func printHelp(c *cli.Command) {
	fmt.Print(helpText(helpName(c)))
}

func helpName(c *cli.Command) string {
	if c.Parent() == nil {
		return "root"
	}
	var parts []string
	for p := c; p.Parent() != nil; p = p.Parent() {
		parts = append([]string{p.Name()}, parts...)
	}
	return strings.Join(parts, "_")
}

func flag(c *cli.Command, name, shorthand, kind, usage, def string) *cli.Flag {
	f := &cli.Flag{Name: name, Shorthand: shorthand, Kind: kind, Usage: usage, Default: def}
	c.Flags = append(c.Flags, f)
	return f
}

const urlUsage = "[driver://username:password@address/dbname?param=value] select a resource using the URL format"
