// runHelp implements the "help" command.
func runHelp(c *cli.Command, args []string) error {
	target := c.Root()
	for _, a := range args {
		found := false
		for _, sub := range target.Commands() {
			if sub.Name() == a {
				target = sub
				found = true
				break
			}
		}
		if !found {
			fmt.Printf("Unknown help topic %#q\n", a)
			return nil
		}
	}
	printHelp(target)
	return nil
}

func runLicense(c *cli.Command, args []string) error {
	fmt.Print(`LICENSE
Atlas is licensed under Apache 2.0 as found in https://github.com/ariga/atlas/blob/master/LICENSE.
`)
	return nil
}

func runVersion(c *cli.Command, args []string) error {
	fmt.Print(`atlas unofficial version - development
https://github.com/ariga/atlas/releases/latest
To download an official version, visit: https://atlasgo.io/getting-started#installation
`)
	return nil
}

// suggestOfficial prints the "community build" trailer at most once per 24h.
func suggestOfficial(err error) {
	if _, ok := err.(*cli.GroupHelpError); ok {
		return
	}
	p := filepath.Join(atlasDir(), "community_error.json")
	if b, err := os.ReadFile(p); err == nil {
		var v struct {
			LastSuggested time.Time `json:"last_suggested"`
		}
		if jsonUnmarshal(b, &v) == nil && time.Since(v.LastSuggested) < 24*time.Hour {
			return
		}
	}
	fmt.Fprint(os.Stderr, `You're running the community build of Atlas, which may differ from the official version.
If this error persists, try installing the official version as a troubleshooting step:

  curl -sSf https://atlasgo.sh | sh

More installation options: https://atlasgo.io/docs#installation
`)
	os.MkdirAll(filepath.Dir(p), 0o755)
	os.WriteFile(p, []byte(fmt.Sprintf(`{"last_suggested":%q}`, time.Now().UTC().Format(time.RFC3339Nano))), 0o644)
}

