func (c *Command) parseFlags(args []string) (positional []string, help bool, err error) {
	all := c.allFlags()
	i := 0
	for i < len(args) {
		a := args[i]
		switch {
		case a == "--":
			positional = append(positional, args[i+1:]...)
			i = len(args)
		case strings.HasPrefix(a, "--"):
			name := a[2:]
			var val string
			var hasVal bool
			if j := strings.Index(name, "="); j != -1 {
				val, name, hasVal = name[j+1:], name[:j], true
			}
			if name == "help" {
				help = true
				break
			}
			f := findFlag(all, name)
			if f == nil {
				return nil, false, &UnknownFlagError{Name: name}
			}
			if f.Kind == "bool" {
				f.BoolVal = true
				if hasVal {
					f.BoolVal = val == "true"
				}
				f.Changed = true
			} else {
				if !hasVal {
					if i+1 >= len(args) {
						return nil, false, fmt.Errorf("flag needs an argument: --%s", name)
					}
					i++
					val = args[i]
				}
				if err := setFlagValue(f, val); err != nil {
					return nil, false, err
				}
			}
		case strings.HasPrefix(a, "-") && a != "-":
			shorts := a[1:]
			for len(shorts) > 0 {
				s := shorts[:1]
				shorts = shorts[1:]
				if s == "h" {
					help = true
					continue
				}
				f := findShort(all, s)
				if f == nil {
					return nil, false, fmt.Errorf("unknown shorthand flag: %q in -%s", rune(s[0]), a[1:])
				}
				if f.Kind == "bool" {
					f.BoolVal = true
					f.Changed = true
					continue
				}
				if len(shorts) > 0 {
					v := shorts
					if strings.HasPrefix(v, "=") {
						v = v[1:]
					}
					if err := setFlagValue(f, v); err != nil {
						return nil, false, err
					}
					shorts = ""
				} else {
					if i+1 >= len(args) {
						return nil, false, fmt.Errorf("flag needs an argument: --%s", f.Name)
					}
					i++
					if err := setFlagValue(f, args[i]); err != nil {
						return nil, false, err
					}
				}
			}
		default:
			positional = append(positional, a)
		}
		i++
	}
	var missing []string
	for _, f := range c.Flags {
		if RequiredFlags[f] && !f.Changed {
			missing = append(missing, f.Name)
		}
	}
	if len(missing) > 0 {
		return nil, false, &RequiredFlagsError{Names: missing}
	}
	return positional, help, nil
}

func setFlagValue(f *Flag, v string) error {
	f.Changed = true
	switch f.Kind {
	case "strings":
		for _, p := range strings.Split(v, ",") {
			f.StrsVal = append(f.StrsVal, p)
		}
	case "vars":
		f.StrsVal = append(f.StrsVal, v)
	case "uint":
