}

func findShort(flags []*Flag, s string) *Flag {
	for _, f := range flags {
		if f.Shorthand == s {
			return f
		}
	}
	return nil
}

func (c *Command) allFlags() []*Flag {
	var out []*Command
	for p := c; p != nil; p = p.parent {
		out = append(out, p)
	}
	var flags []*Flag
	for _, cmd := range out {
		flags = append(flags, cmd.Flags...)
	}
	return flags
}

// ld is a Levenshtein distance implementation (like cobra's ld).
func ld(s, t string, ignoreCase bool) int {
	if ignoreCase {
		s = strings.ToLower(s)
		t = strings.ToLower(t)
	}
	d := make([][]int, len(s)+1)
	for i := range d {
		d[i] = make([]int, len(t)+1)
	}
	for i := range d {
		d[i][0] = i
	}
	for j := range d[0] {
		d[0][j] = j
	}
	for j := 1; j <= len(t); j++ {
		for i := 1; i <= len(s); i++ {
			if s[i-1] == t[j-1] {
				d[i][j] = d[i-1][j-1]
			} else {
				min := d[i-1][j]
				if d[i][j-1] < min {
					min = d[i][j-1]
				}
				if d[i-1][j-1] < min {
					min = d[i-1][j-1]
				}
				d[i][j] = min + 1
			}
		}
	}
	return d[len(s)][len(t)]
}

