	TokPercent     // %
	TokEq          // ==
	TokNeq         // !=
	TokLt          // <
	TokGt          // >
	TokLe          // <=
	TokGe          // >=
	TokAnd         // &&
	TokOr          // ||
	TokNot         // !
	TokFatArrow    // =>
	TokEllipsis    // ...
	TokComment     // #, //, /* */
)

// Pos is a 1-based byte position.
type Pos struct {
	Line, Col int
	Byte      int
}

// Token is a lexed token.
type Token struct {
	Type  TokType
	Text  string
	Start Pos
	End   Pos
}

func (t Token) String() string { return fmt.Sprintf("%d(%q)", t.Type, t.Text) }

func isIdentStart(c byte) bool {
	return c == '_' || c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c >= 0x80
}

func isIdentChar(c byte) bool {
	return isIdentStart(c) || c >= '0' && c <= '9' || c == '-'
}

func isDigit(c byte) bool { return c >= '0' && c <= '9' }

// Lexer state.
type lexer struct {
	src  []byte
	pos  int
	line int
	col  int
	toks []Token
	// template nesting for interp/control tracking
	tmplStack []TokType // TokInterp or TokControl
}

// Lex tokenizes the input.
func Lex(src []byte) ([]Token, error) {
	l := &lexer{src: src, line: 1, col: 1}
	for l.pos < len(l.src) {
		if err := l.scanToken(); err != nil {
			return nil, err
		}
	}
	l.emit(TokEOF, "")
	return l.toks, nil
}

func (l *lexer) cur() byte { return l.src[l.pos] }

func (l *lexer) peek(n int) byte {
	if l.pos+n < len(l.src) {
		return l.src[l.pos+n]
	}
	return 0
}

func (l *lexer) advance() byte {
	c := l.src[l.pos]
	l.pos++
	if c == '\n' {
		l.line++
		l.col = 1
	} else {
		l.col++
	}
	return c
}

func (l *lexer) mark() Pos { return Pos{Line: l.line, Col: l.col, Byte: l.pos} }

func (l *lexer) emit(t TokType, text string) {
	end := l.mark()
	start := Pos{Line: end.Line, Col: end.Col - len(text), Byte: end.Byte - len(text)}
	// recompute start line/col properly for multiline tokens
	if strings.Contains(text, "\n") {
		lines := strings.Split(text, "\n")
		start.Line = end.Line - len(lines) + 1
		if len(lines) == 1 {
			start.Col = end.Col - len(text)
		} else {
			start.Col = end.Col // not exact; rarely used
		}
		// find start col from first line
		start.Col = end.Col
		if len(lines) > 1 {
			// col of token start = col of first char: not tracked; compute from bytes
		}
	}
	_ = start
	l.toks = append(l.toks, Token{Type: t, Text: text, Start: l.lastStart, End: end})
}

// simpler approach: record start before scanning.
func (l *lexer) emitRange(t TokType, start Pos, text string) {
	l.toks = append(l.toks, Token{Type: t, Text: text, Start: start, End: l.mark()})
}

var _ = fmt.Sprintf

func (l *lexer) scanToken() error {
	start := l.mark()
	c := l.cur()
	switch {
	case c == '\n':
		l.advance()
		l.emitRange(TokNewline, start, "\n")
		return nil
	case c == ' ' || c == '\t' || c == '\r':
		l.advance()
		return nil
	case isIdentStart(c):
		s := l.pos
		for l.pos < len(l.src) && isIdentChar(l.cur()) {
			l.advance()
		}
		l.emitRange(TokIdent, start, string(l.src[s:l.pos]))
		return nil
	case isDigit(c):
		s := l.pos
		for l.pos < len(l.src) && isDigit(l.cur()) {
			l.advance()
		}
		if l.pos < len(l.src) && l.cur() == '.' && isDigit(l.peek(1)) {
			l.advance()
			for l.pos < len(l.src) && isDigit(l.cur()) {
				l.advance()
			}
		}
		if l.pos < len(l.src) && (l.cur() == 'e' || l.cur() == 'E') {
			p := l.pos + 1
			if p < len(l.src) && (l.src[p] == '+' || l.src[p] == '-') {
				p++
			}
			if p < len(l.src) && isDigit(l.src[p]) {
				l.advance()
				if l.cur() == '+' || l.cur() == '-' {
					l.advance()
				}
				for l.pos < len(l.src) && isDigit(l.cur()) {
					l.advance()
				}
			}
		}
		l.emitRange(TokNumber, start, string(l.src[s:l.pos]))
		return nil
	case c == '"':
		return l.scanString()
	case c == '#':
		s := l.pos
		for l.pos < len(l.src) && l.cur() != '\n' {
			l.advance()
		}
		l.emitRange(TokComment, start, string(l.src[s:l.pos]))
		return nil
	case c == '/' && l.peek(1) == '/':
		s := l.pos
		for l.pos < len(l.src) && l.cur() != '\n' {
			l.advance()
		}
		l.emitRange(TokComment, start, string(l.src[s:l.pos]))
		return nil
	case c == '/' && l.peek(1) == '*':
		s := l.pos
		l.advance()
		l.advance()
		for l.pos < len(l.src) {
			if l.cur() == '*' && l.peek(1) == '/' {
				l.advance()
				l.advance()
				break
			}
			l.advance()
		}
		l.emitRange(TokComment, start, string(l.src[s:l.pos]))
		return nil
	case c == '<' && l.peek(1) == '<':
		return l.scanHeredoc()
	}

	// template end: } inside interp/control
	if c == '}' && len(l.tmplStack) > 0 {
		l.tmplStack = l.tmplStack[:len(l.tmplStack)-1]
		l.advance()
		l.emitRange(TokTemplateEnd, start, "}")
		return nil
	}

	two := ""
	if l.pos+1 < len(l.src) {
		two = string(l.src[l.pos : l.pos+2])
	}
	three := ""
	if l.pos+2 < len(l.src) {
		three = string(l.src[l.pos : l.pos+3])
	}
	switch three {
	case "...":
		l.advance()
		l.advance()
		l.advance()
		l.emitRange(TokEllipsis, start, three)
		return nil
	}
	switch two {
	case "==":
		l.advance()
		l.advance()
		l.emitRange(TokEq, start, two)
		return nil
	case "!=":
		l.advance()
		l.advance()
		l.emitRange(TokNeq, start, two)
		return nil
	case "<=":
		l.advance()
		l.advance()
		l.emitRange(TokLe, start, two)
		return nil
	case ">=":
		l.advance()
		l.advance()
		l.emitRange(TokGe, start, two)
		return nil
	case "&&":
		l.advance()
		l.advance()
		l.emitRange(TokAnd, start, two)
		return nil
	case "||":
		l.advance()
		l.advance()
		l.emitRange(TokOr, start, two)
		return nil
	case "=>":
		l.advance()
		l.advance()
		l.emitRange(TokFatArrow, start, two)
		return nil
	}
	single := map[byte]TokType{
		'{': TokOBrace, '}': TokCBrace,
		'[': TokOBrack, ']': TokCBrack,
		'(': TokOParen, ')': TokCParen,
		'=': TokAssign, ',': TokComma, '.': TokDot, ':': TokColon,
		'?': TokQuestion, '+': TokPlus, '-': TokMinus, '*': TokStar,
		'/': TokSlash, '%': TokPercent, '<': TokLt, '>': TokGt, '!': TokNot,
	}
	if t, ok := single[c]; ok {
		l.advance()
		l.emitRange(t, start, string(c))
		return nil
	}
	return fmt.Errorf("unexpected character %q at %d:%d", c, start.Line, start.Col)
}

// scanString scans a quoted string, splitting interpolations.
func (l *lexer) scanString() error {
	start := l.mark()
	s := l.pos
	l.advance() // consume "
	var parts []Token
	partStart := s
	flush := func() {
		if l.pos > partStart {
			parts = append(parts, Token{Type: TokStringPart, Text: string(l.src[partStart:l.pos])})
		}
	}
	for l.pos < len(l.src) {
		c := l.cur()
		if c == '\\' {
			l.advance()
			if l.pos < len(l.src) {
				l.advance()
			}
			continue
		}
		if c == '$' && l.peek(1) == '{' {
			flush()
			pstart := l.mark()
			l.advance()
			l.advance()
			parts = append(parts, Token{Type: TokInterp, Text: "${", Start: pstart})
			l.tmplStack = append(l.tmplStack, TokInterp)
			partStart = l.pos
			// emit opening quote + parts
			return l.finishString(start, parts)
		}
		if c == '%' && l.peek(1) == '{' {
			flush()
			pstart := l.mark()
			l.advance()
			l.advance()
			parts = append(parts, Token{Type: TokControl, Text: "%{", Start: pstart})
			l.tmplStack = append(l.tmplStack, TokControl)
			partStart = l.pos
			return l.finishString(start, parts)
		}
		if c == '"' {
			l.advance()
			if len(parts) == 0 {
				l.emitRange(TokStringLit, start, string(l.src[s:l.pos]))
				return nil
			}
			flush()
			parts = append(parts, Token{Type: TokCQuote, Text: `"`})
			return l.finishString(start, parts)
		}
		l.advance()
	}
	return fmt.Errorf("unterminated string at %d:%d", start.Line, start.Col)
}

// finishString emits an interpolated string: OQuote, parts..., then continues
// lexing (the interp contents are lexed by the main loop; TokTemplateEnd
// returns here via a marker trick: we keep a pending continuation).
func (l *lexer) finishString(start Pos, parts []Token) error {
	// Emit OQuote covering up to the first interp/control.
	if len(parts) > 0 && (parts[0].Type == TokStringPart) {
		l.toks = append(l.toks, Token{Type: TokOQuote, Text: `"`, Start: start})
		l.toks = append(l.toks, parts[0])
		parts = parts[1:]
	} else {
		l.toks = append(l.toks, Token{Type: TokOQuote, Text: `"`, Start: start})
	}
	// The first non-stringpart token is ${ or %{.
	if len(parts) > 0 {
		l.toks = append(l.toks, parts[0])
		// Queue continuation: after the matching TemplateEnd, resume string scan.
		l.strCont = append(l.strCont, strCont{quoteStart: start})
	} else {
		// empty string ""
		l.toks = append(l.toks, Token{Type: TokCQuote, Text: `"`})
	}
	return nil
}

// strCont represents a pending string continuation after a template end.
type strCont struct {
	quoteStart Pos
}

