// Package hcl implements a lexer, formatter, parser and evaluator for the
// HCL configuration language subset needed by this tool. The behavior is
// modeled after the observable output of the reference binary.
package hcl

import (
	"fmt"
	"strings"
)

// TokType enumerates token types.
type TokType int

const (
	TokEOF TokType = iota
	TokNewline
	TokIdent
	TokNumber
	TokStringLit   // a complete quoted string without interpolation
	TokStringPart  // literal part of an interpolated string (incl. quotes on edges)
	TokInterp      // ${
	TokControl     // %{
	TokTemplateEnd // } closing an interp/control
	TokOHeredoc    // <<MARK or <<-MARK
	TokHeredocBody // frozen heredoc content (including newlines)
	TokCHeredoc    // heredoc end marker line (with leading space)
	TokOBrace      // {
	TokCBrace      // }
	TokOBrack      // [
	TokCBrack      // ]
	TokOParen      // (
	TokCParen      // )
	TokAssign      // =
	TokComma       // ,
	TokDot         // .
	TokColon       // :
	TokQuestion    // ?
	TokPlus        // +
	TokMinus       // -
	TokStar        // *
	TokSlash       // /
	TokPercent     // %
	TokEq          // ==
	TokNeq         // !=
	TokLt          // <
	TokGt          // >
	TokLe          // <=
	TokGe          // >=
	TokAnd         // &&
	TokOr          // ||
	TokNot         // !
	TokFatArrow    // =>
	TokEllipsis    // ...
	TokComment     // #, //, /* */
)

// Pos is a 1-based position.
type Pos struct {
	Line, Col int
	Byte      int
}

// Token is a lexed token.
type Token struct {
	Type  TokType
	Text  string
	Start Pos
	End   Pos
}

func isIdentStart(c byte) bool {
	return c == '_' || c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c >= 0x80
}

func isIdentChar(c byte) bool {
	return isIdentStart(c) || c >= '0' && c <= '9' || c == '-'
}

func isDigit(c byte) bool { return c >= '0' && c <= '9' }

type lexer struct {
	src  []byte
	pos  int
	line int
	col  int
	toks []Token
	// tmplStack tracks open ${ and %{.
	tmplStack []TokType
	// inString: currently scanning a string continuation (after TemplateEnd).
}

// Lex tokenizes the input.
func Lex(src []byte) ([]Token, error) {
	l := &lexer{src: src, line: 1, col: 1}
	for l.pos < len(l.src) {
		if err := l.scanToken(); err != nil {
			return nil, err
		}
	}
	l.emit(TokEOF, "", l.mark(), l.mark())
	return l.toks, nil
}

func (l *lexer) cur() byte { return l.src[l.pos] }

func (l *lexer) peek(n int) byte {
	if l.pos+n < len(l.src) {
		return l.src[l.pos+n]
	}
	return 0
}

func (l *lexer) advance() byte {
	c := l.src[l.pos]
	l.pos++
	if c == '\n' {
		l.line++
		l.col = 1
	} else {
		l.col++
	}
	return c
}

func (l *lexer) mark() Pos { return Pos{Line: l.line, Col: l.col, Byte: l.pos} }

func (l *lexer) emit(t TokType, text string, start, end Pos) {
	l.toks = append(l.toks, Token{Type: t, Text: text, Start: start, End: end})
}

func (l *lexer) scanToken() error {
	start := l.mark()
	c := l.cur()
	switch {
	case c == '\n':
		l.advance()
		l.emit(TokNewline, "\n", start, l.mark())
		return nil
	case c == ' ' || c == '\t' || c == '\r':
		l.advance()
		return nil
	case isIdentStart(c):
		s := l.pos
		for l.pos < len(l.src) && isIdentChar(l.cur()) {
			l.advance()
		}
		l.emit(TokIdent, string(l.src[s:l.pos]), start, l.mark())
		return nil
	case isDigit(c):
		l.scanNumber(start)
		return nil
	case c == '"':
		return l.scanString(start)
	case c == '#' || c == '/' && l.peek(1) == '/':
		s := l.pos
		for l.pos < len(l.src) && l.cur() != '\n' {
			l.advance()
		}
		l.emit(TokComment, string(l.src[s:l.pos]), start, l.mark())
		return nil
	case c == '/' && l.peek(1) == '*':
		s := l.pos
		l.advance()
		l.advance()
		for l.pos < len(l.src) {
			if l.cur() == '*' && l.peek(1) == '/' {
				l.advance()
				l.advance()
				break
			}
			l.advance()
		}
		l.emit(TokComment, string(l.src[s:l.pos]), start, l.mark())
		return nil
	case c == '<' && l.peek(1) == '<':
		return l.scanHeredoc(start)
	case c == '}' && len(l.tmplStack) > 0:
		l.tmplStack = l.tmplStack[:len(l.tmplStack)-1]
		l.advance()
		l.emit(TokTemplateEnd, "}", start, l.mark())
		return nil
	}

	two := ""
	if l.pos+1 < len(l.src) {
		two = string(l.src[l.pos : l.pos+2])
	}
	switch two {
	case "==", "!=", "<=", ">=", "&&", "||", "=>":
		l.advance()
		l.advance()
		typ := map[string]TokType{
			"==": TokEq, "!=": TokNeq, "<=": TokLe, ">=": TokGe,
			"&&": TokAnd, "||": TokOr, "=>": TokFatArrow,
		}[two]
		l.emit(typ, two, start, l.mark())
		return nil
	}
	if l.pos+2 < len(l.src) && string(l.src[l.pos:l.pos+3]) == "..." {
		l.advance()
		l.advance()
		l.advance()
		l.emit(TokEllipsis, "...", start, l.mark())
		return nil
	}
	single := map[byte]TokType{
		'{': TokOBrace, '}': TokCBrace,
		'[': TokOBrack, ']': TokCBrack,
		'(': TokOParen, ')': TokCParen,
		'=': TokAssign, ',': TokComma, '.': TokDot, ':': TokColon,
		'?': TokQuestion, '+': TokPlus, '-': TokMinus, '*': TokStar,
		'/': TokSlash, '%': TokPercent, '<': TokLt, '>': TokGt, '!': TokNot,
	}
	if t, ok := single[c]; ok {
		l.advance()
		l.emit(t, string(c), start, l.mark())
		return nil
	}
	return fmt.Errorf("unexpected character %q at %d:%d", c, start.Line, start.Col)
}

func (l *lexer) scanNumber(start Pos) {
	s := l.pos
	for l.pos < len(l.src) && isDigit(l.cur()) {
		l.advance()
	}
	if l.pos < len(l.src) && l.cur() == '.' && isDigit(l.peek(1)) {
		l.advance()
		for l.pos < len(l.src) && isDigit(l.cur()) {
			l.advance()
		}
	}
	if l.pos < len(l.src) && (l.cur() == 'e' || l.cur() == 'E') {
		p := l.pos + 1
		if p < len(l.src) && (l.src[p] == '+' || l.src[p] == '-') {
			p++
		}
		if p < len(l.src) && isDigit(l.src[p]) {
			l.advance()
			if l.cur() == '+' || l.cur() == '-' {
				l.advance()
			}
			for l.pos < len(l.src) && isDigit(l.cur()) {
				l.advance()
			}
		}
	}
	l.emit(TokNumber, string(l.src[s:l.pos]), start, l.mark())
}

// scanString scans a quoted string starting at the opening quote. It emits
// TokStringPart chunks and interp/control tokens; interp contents are lexed
// by the main loop and TokTemplateEnd brings us back here.
func (l *lexer) scanString(start Pos) error {
	s := l.pos
	l.advance() // opening quote
	partStart := s
	for l.pos < len(l.src) {
		c := l.cur()
		switch {
		case c == '\\':
			l.advance()
			if l.pos < len(l.src) {
				l.advance()
			}
		case c == '$' && l.peek(1) == '{':
			// emit part up to ${ (including opening quote)
			l.emit(TokStringPart, string(l.src[partStart:l.pos]), start, l.mark())
			istart := l.mark()
			l.advance()
			l.advance()
			l.emit(TokInterp, "${", istart, l.mark())
			l.tmplStack = append(l.tmplStack, TokInterp)
			return nil
		case c == '%' && l.peek(1) == '{':
			l.emit(TokStringPart, string(l.src[partStart:l.pos]), start, l.mark())
			istart := l.mark()
			l.advance()
			l.advance()
			l.emit(TokControl, "%{", istart, l.mark())
			l.tmplStack = append(l.tmplStack, TokControl)
			return nil
		case c == '"':
			l.advance()
			text := string(l.src[s:l.pos])
			if partStart == s && !strings.ContainsAny(text, "${") {
				// plain string (no interpolation encountered)
				l.emit(TokStringLit, text, start, l.mark())
			} else {
				l.emit(TokStringPart, text[0:], start, l.mark())
			}
			return nil
		default:
			l.advance()
		}
	}
	return fmt.Errorf("unterminated string")
}

// scanStringCont continues a string after a template end; called when the
// lexer resumes inside a string.
func (l *lexer) scanStringCont() error {
	start := l.mark()
	partStart := l.pos
	for l.pos < len(l.src) {
		c := l.cur()
		switch {
		case c == '\\':
			l.advance()
			if l.pos < len(l.src) {
				l.advance()
			}
		case c == '$' && l.peek(1) == '{':
			if l.pos > partStart {
				l.emit(TokStringPart, string(l.src[partStart:l.pos]), start, l.mark())
			}
			istart := l.mark()
			l.advance()
			l.advance()
			l.emit(TokInterp, "${", istart, l.mark())
			l.tmplStack = append(l.tmplStack, TokInterp)
			return nil
		case c == '%' && l.peek(1) == '{':
			if l.pos > partStart {
				l.emit(TokStringPart, string(l.src[partStart:l.pos]), start, l.mark())
			}
			istart := l.mark()
			l.advance()
			l.advance()
			l.emit(TokControl, "%{", istart, l.mark())
			l.tmplStack = append(l.tmplStack, TokControl)
			return nil
		case c == '"':
			l.advance()
			l.emit(TokStringPart, string(l.src[partStart:l.pos]), start, l.mark())
			return nil
		default:
			l.advance()
		}
	}
	return fmt.Errorf("unterminated string")
}

// scanHeredoc scans <<MARK / <<-MARK, the body and the end marker.
func (l *lexer) scanHeredoc(start Pos) error {
	s := l.pos
	l.advance()
	l.advance()
	trim := false
	if l.pos < len(l.src) && l.cur() == '-' {
		trim = true
		l.advance()
	}
	mstart := l.pos
	for l.pos < len(l.src) && (isIdentChar(l.cur())) {
		l.advance()
	}
	marker := string(l.src[mstart:l.pos])
	l.emit(TokOHeredoc, string(l.src[s:l.pos]), start, l.mark())
	// rest of line until newline
	for l.pos < len(l.src) && l.cur() != '\n' {
		l.advance()
	}
	// body: read lines until marker line
	bodyStart := l.mark()
	for l.pos < len(l.src) {
		lineStart := l.pos
		linePos := l.mark()
		for l.pos < len(l.src) && l.cur() != '\n' {
			l.advance()
		}
		content := string(l.src[lineStart:l.pos])
		end := content
		if trim {
			end = strings.TrimLeft(end, " \t")
		}
		if end == marker {
			// emit body (everything before this line)
			l.emit(TokHeredocBody, string(l.src[bodyStart.Byte:lineStart]), bodyStart, linePos)
			l.emit(TokCHeredoc, content, linePos, l.mark())
			return nil
		}
		if l.pos < len(l.src) {
			l.advance() // newline
		}
	}
	return fmt.Errorf("unterminated heredoc")
}

