	}
}

var lnIndent = map[*formatLine]int{}

// render rebuilds the source.
func render(lines []*formatLine) []byte {
	// alignment groups
	alignGroup := map[*formatLine]int // line -> padded lhs width (0 = no alignment)
	var group []*formatLine
	flush := func() {
		if len(group) == 0 {
			return
		}
		max := 0
		for _, ln := range group {
			if w := lhsWidth(ln); w > max {
				max = w
			}
		}
		for _, ln := range group {
			alignGroup[ln] = max
		}
		group = nil
	}
	for _, ln := range lines {
		if ln.frozen {
			continue // heredoc body lines do not break alignment groups
		}
		if alignable(ln) {
			group = append(group, ln)
		} else {
			flush()
		}
	}
	flush()

	var b strings.Builder
	for _, ln := range lines {
		if ln.frozen {
			for _, t := range ln.toks {
				b.WriteString(t.Text)
			}
			if ln.hasNL {
				b.WriteString("\n")
			}
			continue
		}
		if len(ln.toks) == 0 {
			if ln.hasNL {
				b.WriteString("\n")
			}
			continue
		}
		indent := lnIndent[ln]
		b.WriteString(strings.Repeat("  ", indent))
		if w, ok := alignGroup[ln]; ok {
			renderAligned(&b, ln, w)
		} else {
			renderSpaced(&b, ln.toks)
		}
		if ln.hasNL {
			b.WriteString("\n")
		}
	}
	return []byte(b.String())
}

// alignable reports whether the line is a single-line attribute that can
// participate in = alignment.
func alignable(ln *formatLine) bool {
	if len(ln.toks) == 0 || ln.frozen {
		return false
	}
	hasAssign := false
	depth := 0
	for _, t := range ln.toks {
		if t.Type == TokAssign {
			hasAssign = true
		}
		if isOpen(t.Type) {
			depth++
		}
		if isClose(t.Type) {
			depth--
		}
	}
	return hasAssign && depth == 0
}

// firstAssign returns the index of the first assign token.
func firstAssign(ln *formatLine) int {
	for i, t := range ln.toks {
		if t.Type == TokAssign {
			return i
		}
	}
	return -1
}

// lhsWidth computes the rendered width of the LHS before the assign.
func lhsWidth(ln *formatLine) int {
	i := firstAssign(ln)
	var b strings.Builder
	renderSpaced(&b, ln.toks[:i])
	return b.Len()
}

// renderAligned renders an attribute line with the = aligned at width w.
func renderAligned(b *strings.Builder, ln *formatLine, w int) {
	i := firstAssign(ln)
	var lhs strings.Builder
	renderSpaced(&lhs, ln.toks[:i])
	b.WriteString(lhs.String())
	for j := lhs.Len(); j < w; j++ {
		b.WriteString(" ")
	}
	b.WriteString(" = ")
	renderSpaced(b, ln.toks[i+1:])
}

// renderSpaced renders tokens with canonical spacing.
func renderSpaced(b *strings.Builder, toks []Token) {
	for i, t := range toks {
		if i > 0 {
			if spaceBetween(toks[i-1], t, toks, i) {
				b.WriteString(" ")
			}
		}
		b.WriteString(t.Text)
	}
}

// spaceBetween decides whether a space goes between prev and cur.
func spaceBetween(prev, cur Token, toks []Token, i int) bool {
	switch cur.Type {
	case TokCParen, TokCBrack, TokComma, TokDot, TokTemplateEnd, TokInterp, TokControl:
		return false
	}
	switch prev.Type {
	case TokOParen, TokOBrack, TokDot, TokInterp, TokControl, TokTemplateEnd:
		return false
	case TokNot:
		return false
	case TokMinus:
		if isUnaryMinus(toks, i-1) {
			return false
		}
	}
	if cur.Type == TokOParen && prev.Type == TokIdent {
		return false // function call
	}
	if cur.Type == TokOBrack {
		switch prev.Type {
		case TokIdent, TokNumber, TokStringLit, TokStringPart, TokCBrack, TokCParen, TokTemplateEnd:
			return false // index
		}
	}
	return true
}

// isUnaryMinus reports whether toks[i] (a minus) is a unary minus.
func isUnaryMinus(toks []Token, i int) bool {
	if i == 0 {
		return true
	}
	switch toks[i-1].Type {
	case TokIdent, TokNumber, TokStringLit, TokStringPart, TokCParen, TokCBrack, TokTemplateEnd:
		return false
	}
	return true
}
